const raw = $input.first().json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('Invalid JSON from Groq: ' + raw.slice(0, 500));
}

const s = parsed.scores;
const r = parsed.rationales;

if (!s || !r) {
  throw new Error('Groq response missing scores or rationales: ' + raw.slice(0, 500));
}

const total = (s.process_thinking || 0) + (s.practical_automation || 0) +
              (s.clarity_communication || 0) + (s.execution_logic || 0) +
              (s.reliability_awareness || 0);

let outcome;
if (total >= 20) outcome = 'Advance';
else if (total >= 15) outcome = 'Review';
else outcome = 'Reject';

const prev = $('Build Scoring Request').first().json;

return [{ json: {
  candidateId: prev.candidateId,
  candidateName: prev.candidateName,
  scores: s,
  rationales: r,
  total,
  outcome
}}];

const ctx = $input.first().json;
const trigger = $('Airtable Trigger').first().json;
const f = trigger.fields;

const systemPrompt = [
  "You generate exactly ONE short sentence (10-25 words) to be inserted into a hiring email.",
  "Follow the rules for the given outcome strictly.",
  "",
  "For Advance: Reference the strongest specific element of the candidate's answers. Be warm and specific.",
  "For Review: Be neutral and brief. Acknowledge their effort. NEVER hint they are borderline.",
  "For Reject: Be neutral, brief, and encouraging. NEVER give reasons for rejection. NEVER reference weaknesses.",
  "",
  "Return only the sentence. No quotes, no prose around it, no preamble."
].join("\n");

const userPrompt = [
  "Outcome: " + ctx.outcome,
  "Candidate name: " + ctx.candidateName,
  "",
  "Their past experience: " + (f['Past Experience'] || ""),
  "Their AI usage example: " + (f['AI Usage Example'] || ""),
  "Their Q1 answer: " + (f['Q1 Answer'] || ""),
  "",
  "Generate the one sentence now."
].join("\n");

return [{ json: {
  ...ctx,
  linePayload: {
    model: "llama-3.3-70b-versatile",
    temperature: 0.7,
    max_tokens: 80,
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userPrompt }
    ]
  }
}}];

const line = $input.first().json.choices[0].message.content.trim();
const prev = $('Build Line Request').first().json;

return [{ json: {
  candidateId: prev.candidateId,
  candidateName: prev.candidateName,
  scores: prev.scores,
  rationales: prev.rationales,
  total: prev.total,
  outcome: prev.outcome,
  personalizedLine: line
}}];

const tpl = $input.first().json.fields;
const ctx = $('Extract Line').first().json;

const subject = tpl.Subject || '';
const body = (tpl.Body || '')
  .split('{{name}}').join(ctx.candidateName)
  .split('{{personalized_line}}').join(ctx.personalizedLine);

return [{ json: {
  ...ctx,
  subject,
  body
}}];
